CREATE TYPE "HrFinalSettlementStatus" AS ENUM ('DRAFT','APPROVED','PARTIALLY_PAID','PAID','REVERSED','CANCELLED');
CREATE TYPE "HrFinalSettlementReason" AS ENUM ('EMPLOYER_TERMINATION','RESIGNATION','ARTICLE_80','ARTICLE_81','FORCE_MAJEURE','MATERNITY','OTHER_LEGAL_REVIEW');
CREATE TYPE "HrFinalSettlementReasonVerificationStatus" AS ENUM ('PENDING','VERIFIED','REJECTED');
CREATE TYPE "HrFinalSettlementRecoveryType" AS ENUM ('ADVANCE','ADMINISTRATIVE_DEDUCTION');
ALTER TYPE "HrEmployeeFinancialMovementType" ADD VALUE 'FINAL_SETTLEMENT_ACCRUAL';
ALTER TYPE "HrEmployeeFinancialMovementType" ADD VALUE 'FINAL_SETTLEMENT_PAYMENT';
ALTER TYPE "HrEmployeeAdvanceSettlementSource" ADD VALUE 'FINAL_SETTLEMENT';
CREATE TABLE "HrFinalSettlement" ("id" uuid PRIMARY KEY,"tenantId" uuid NOT NULL,"companyId" uuid NOT NULL,"employeeId" uuid NOT NULL,"settlementNumber" varchar(80) NOT NULL,"status" "HrFinalSettlementStatus" NOT NULL DEFAULT 'DRAFT',"terminationDate" date NOT NULL,"terminationReason" "HrFinalSettlementReason" NOT NULL,"reasonEvidenceReference" varchar(240) NOT NULL,"reasonEvidenceNote" varchar(2000),"reasonVerificationStatus" "HrFinalSettlementReasonVerificationStatus" NOT NULL DEFAULT 'PENDING',"reasonVerifiedAt" timestamptz(6),"reasonVerifiedByUserId" uuid,"reasonVerificationNote" varchar(2000),"calculationPolicyVersion" varchar(40) NOT NULL,"serviceDays" integer NOT NULL,"eosWage" decimal(18,4) NOT NULL,"fullAwardAmount" decimal(18,4) NOT NULL,"entitlementFactor" decimal(10,8) NOT NULL,"eosAmount" decimal(18,4) NOT NULL,"otherCreditsAmount" decimal(18,4) NOT NULL DEFAULT 0,"recoveryAmount" decimal(18,4) NOT NULL DEFAULT 0,"netPayableAmount" decimal(18,4) NOT NULL,"paidAmount" decimal(18,4) NOT NULL DEFAULT 0,"snapshotJson" jsonb NOT NULL,"snapshotSha256" char(64) NOT NULL,"accrualJournalEntryId" uuid,"approvedAt" timestamptz(6),"approvedByUserId" uuid,"reversedAt" timestamptz(6),"reversedByUserId" uuid,"reversalReason" varchar(1000),"createdByUserId" uuid NOT NULL,"createdAt" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamptz(6) NOT NULL);
CREATE UNIQUE INDEX "HrFinalSettlement_scope_id_key" ON "HrFinalSettlement"("id","tenantId","companyId"); CREATE UNIQUE INDEX "HrFinalSettlement_number_key" ON "HrFinalSettlement"("companyId","settlementNumber"); CREATE UNIQUE INDEX "HrFinalSettlement_journal_key" ON "HrFinalSettlement"("accrualJournalEntryId","tenantId","companyId"); CREATE INDEX "HrFinalSettlement_employee_status_idx" ON "HrFinalSettlement"("tenantId","companyId","employeeId","status","terminationDate"); CREATE INDEX "HrFinalSettlement_created_keyset_idx" ON "HrFinalSettlement"("tenantId","companyId","createdAt" DESC,"id" DESC);
ALTER TABLE "HrFinalSettlement" ADD CONSTRAINT "HrFinalSettlement_company_fkey" FOREIGN KEY("companyId","tenantId") REFERENCES "Company"("id","tenantId") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "HrFinalSettlement_employee_fkey" FOREIGN KEY("employeeId","tenantId","companyId") REFERENCES "HrEmployee"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "HrFinalSettlement_journal_fkey" FOREIGN KEY("accrualJournalEntryId","tenantId","companyId") REFERENCES "FinanceJournalEntry"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "HrFinalSettlementRecovery" ("id" uuid PRIMARY KEY,"tenantId" uuid NOT NULL,"companyId" uuid NOT NULL,"settlementId" uuid NOT NULL,"recoveryType" "HrFinalSettlementRecoveryType" NOT NULL,"sourceId" uuid NOT NULL,"amount" decimal(18,4) NOT NULL,"createdAt" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("settlementId","recoveryType","sourceId")); CREATE INDEX "HrFinalSettlementRecovery_source_idx" ON "HrFinalSettlementRecovery"("tenantId","companyId","recoveryType","sourceId"); ALTER TABLE "HrFinalSettlementRecovery" ADD CONSTRAINT "HrFinalSettlementRecovery_settlement_fkey" FOREIGN KEY("settlementId","tenantId","companyId") REFERENCES "HrFinalSettlement"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "HrFinalSettlementPayment" ("id" uuid PRIMARY KEY,"tenantId" uuid NOT NULL,"companyId" uuid NOT NULL,"settlementId" uuid NOT NULL,"paymentNumber" varchar(80) NOT NULL,"businessDate" date NOT NULL,"amount" decimal(18,4) NOT NULL,"journalEntryId" uuid NOT NULL,"createdByUserId" uuid NOT NULL,"createdAt" timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("id","tenantId","companyId"), UNIQUE("companyId","paymentNumber"), UNIQUE("journalEntryId","tenantId","companyId")); ALTER TABLE "HrFinalSettlementPayment" ADD CONSTRAINT "HrFinalSettlementPayment_settlement_fkey" FOREIGN KEY("settlementId","tenantId","companyId") REFERENCES "HrFinalSettlement"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "HrFinalSettlementPayment_journal_fkey" FOREIGN KEY("journalEntryId","tenantId","companyId") REFERENCES "FinanceJournalEntry"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "HrFinalSettlementPaymentAllocation" ("id" uuid PRIMARY KEY,"tenantId" uuid NOT NULL,"companyId" uuid NOT NULL,"paymentId" uuid NOT NULL,"vaultId" uuid NOT NULL,"paymentMethod" "FinanceVaultPaymentMethod" NOT NULL,"amount" decimal(18,4) NOT NULL, UNIQUE("paymentId","vaultId","paymentMethod")); ALTER TABLE "HrFinalSettlementPaymentAllocation" ADD CONSTRAINT "HrFinalSettlementPaymentAllocation_payment_fkey" FOREIGN KEY("paymentId","tenantId","companyId") REFERENCES "HrFinalSettlementPayment"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "HrFinalSettlementPaymentAllocation_vault_fkey" FOREIGN KEY("vaultId","tenantId","companyId") REFERENCES "FinanceVault"("id","tenantId","companyId") ON DELETE RESTRICT ON UPDATE CASCADE;
